-- Generic ANSI SQL. FKs to orders.order_id are commented out because raw
-- orders contain duplicate order_ids (API re-sends).

CREATE TABLE customers (
    customer_id              VARCHAR(10) NOT NULL,
    customer_name            VARCHAR(40) NOT NULL,
    segment                  VARCHAR(20) NOT NULL,
    country_code             VARCHAR(2) NOT NULL,
    city                     VARCHAR(10),
    credit_limit_eur         DECIMAL(12,2) NOT NULL,
    credit_status            VARCHAR(5) NOT NULL,
    created_at               TIMESTAMP NOT NULL,
    last_modified_at         TIMESTAMP NOT NULL,
    CONSTRAINT pk_customers PRIMARY KEY (customer_id)
);

CREATE TABLE products (
    sku                      VARCHAR(10) NOT NULL,
    product_name             VARCHAR(40) NOT NULL,
    category                 VARCHAR(20) NOT NULL,
    list_price_eur           DECIMAL(12,2) NOT NULL,
    unit_cost_eur            DECIMAL(12,2) NOT NULL,
    weight_kg                DECIMAL(10,2) NOT NULL,
    storage_bay              VARCHAR(10) NOT NULL,
    is_active                VARCHAR(2) NOT NULL,
    created_at               TIMESTAMP NOT NULL,
    CONSTRAINT pk_products PRIMARY KEY (sku)
);

CREATE TABLE product_price_history (
    sku                      VARCHAR(10) NOT NULL,
    list_price_eur           DECIMAL(12,2) NOT NULL,
    valid_from               DATE NOT NULL,
    valid_to                 DATE,
    CONSTRAINT pk_product_price_history PRIMARY KEY (sku, valid_from),
    CONSTRAINT fk_product_price_history_sku FOREIGN KEY (sku) REFERENCES products (sku)
);

CREATE TABLE pickers (
    picker_id                VARCHAR(5) NOT NULL,
    picker_name              VARCHAR(20) NOT NULL,
    shift                    VARCHAR(5) NOT NULL,
    employment_type          VARCHAR(10) NOT NULL,
    hire_date                DATE NOT NULL,
    termination_date         DATE,
    CONSTRAINT pk_pickers PRIMARY KEY (picker_id)
);

CREATE TABLE carriers (
    carrier_code             VARCHAR(3) NOT NULL,
    carrier_name             VARCHAR(40) NOT NULL,
    pickup_times_weekday     VARCHAR(40) NOT NULL,
    pickup_times_saturday    VARCHAR(20) NOT NULL,
    contracted_transit_days  INTEGER NOT NULL,
    base_rate_eur            DECIMAL(12,2) NOT NULL,
    rate_per_kg_eur          DECIMAL(12,2) NOT NULL,
    CONSTRAINT pk_carriers PRIMARY KEY (carrier_code)
);

CREATE TABLE orders (
    order_id                 VARCHAR(10) NOT NULL,
    api_message_id           VARCHAR(40) NOT NULL,
    customer_id              VARCHAR(10) NOT NULL,
    channel                  VARCHAR(20) NOT NULL,
    priority                 VARCHAR(10) NOT NULL,
    received_ts              TIMESTAMP NOT NULL,
    ingested_ts              TIMESTAMP NOT NULL,
    validated_ts             TIMESTAMP,
    validation_result        VARCHAR(10),
    validation_reason        VARCHAR(40),
    credit_status_at_order   VARCHAR(5) NOT NULL,
    customer_notified_ts     TIMESTAMP,
    promised_ship_by_ts      TIMESTAMP,
    order_status             VARCHAR(20) NOT NULL,
    CONSTRAINT pk_orders PRIMARY KEY (api_message_id),
    CONSTRAINT fk_orders_customer_id FOREIGN KEY (customer_id) REFERENCES customers (customer_id)
);

CREATE TABLE order_lines (
    order_id                 VARCHAR(10) NOT NULL,
    line_no                  INTEGER NOT NULL,
    sku                      VARCHAR(10) NOT NULL,
    ordered_qty              INTEGER NOT NULL,
    unit_price_eur           DECIMAL(12,2) NOT NULL,
    discount_pct             DECIMAL(10,2) NOT NULL,
    CONSTRAINT pk_order_lines PRIMARY KEY (order_id, line_no),
--  CONSTRAINT fk_order_lines_order_id FOREIGN KEY (order_id) REFERENCES orders (order_id)   -- not enforceable on raw data
    CONSTRAINT fk_order_lines_sku FOREIGN KEY (sku) REFERENCES products (sku)
);

CREATE TABLE inventory_reservations (
    reservation_id           VARCHAR(10) NOT NULL,
    order_id                 VARCHAR(10) NOT NULL,
    line_no                  INTEGER NOT NULL,
    sku                      VARCHAR(10) NOT NULL,
    available_qty_before     INTEGER NOT NULL,
    reserved_qty             INTEGER NOT NULL,
    reservation_ts           TIMESTAMP NOT NULL,
    CONSTRAINT pk_inventory_reservations PRIMARY KEY (reservation_id),
    CONSTRAINT fk_inventory_reservations_order_id_line_no FOREIGN KEY (order_id, line_no) REFERENCES order_lines (order_id, line_no),
    CONSTRAINT fk_inventory_reservations_sku FOREIGN KEY (sku) REFERENCES products (sku)
);

CREATE TABLE backorders (
    backorder_id             VARCHAR(10) NOT NULL,
    order_id                 VARCHAR(10) NOT NULL,
    line_no                  INTEGER NOT NULL,
    sku                      VARCHAR(10) NOT NULL,
    ordered_qty              INTEGER NOT NULL,
    available_qty            INTEGER NOT NULL,
    backorder_qty            INTEGER NOT NULL,
    backorder_reason         VARCHAR(20) NOT NULL,
    expected_restock_date    DATE,
    backorder_ts             TIMESTAMP NOT NULL,
    notice_sent_ts           TIMESTAMP NOT NULL,
    CONSTRAINT pk_backorders PRIMARY KEY (backorder_id),
    CONSTRAINT fk_backorders_order_id_line_no FOREIGN KEY (order_id, line_no) REFERENCES order_lines (order_id, line_no),
    CONSTRAINT fk_backorders_sku FOREIGN KEY (sku) REFERENCES products (sku)
);

CREATE TABLE inventory_snapshots (
    snapshot_date            DATE NOT NULL,
    sku                      VARCHAR(10) NOT NULL,
    on_hand_qty              INTEGER NOT NULL,
    reserved_qty             INTEGER NOT NULL,
    available_qty            INTEGER NOT NULL,
    on_order_qty             INTEGER NOT NULL,
    reorder_point            INTEGER NOT NULL,
    stockout_flag            VARCHAR(2) NOT NULL,
    CONSTRAINT pk_inventory_snapshots PRIMARY KEY (snapshot_date, sku),
    CONSTRAINT fk_inventory_snapshots_sku FOREIGN KEY (sku) REFERENCES products (sku)
);

CREATE TABLE pick_tasks (
    pick_task_id             VARCHAR(10) NOT NULL,
    order_id                 VARCHAR(10) NOT NULL,
    line_no                  INTEGER NOT NULL,
    queue_name               VARCHAR(10) NOT NULL,
    picker_id                VARCHAR(5) NOT NULL,
    released_ts              TIMESTAMP NOT NULL,
    assigned_ts              TIMESTAMP NOT NULL,
    pick_start_ts            TIMESTAMP NOT NULL,
    pick_end_ts              TIMESTAMP NOT NULL,
    storage_bay              VARCHAR(10) NOT NULL,
    ordered_sku              VARCHAR(10) NOT NULL,
    picked_sku               VARCHAR(10) NOT NULL,
    ordered_qty              INTEGER NOT NULL,
    picked_qty               INTEGER NOT NULL,
    task_status              VARCHAR(10) NOT NULL,
    CONSTRAINT pk_pick_tasks PRIMARY KEY (pick_task_id),
    CONSTRAINT fk_pick_tasks_order_id_line_no FOREIGN KEY (order_id, line_no) REFERENCES order_lines (order_id, line_no),
    CONSTRAINT fk_pick_tasks_picker_id FOREIGN KEY (picker_id) REFERENCES pickers (picker_id),
    CONSTRAINT fk_pick_tasks_ordered_sku FOREIGN KEY (ordered_sku) REFERENCES products (sku),
    CONSTRAINT fk_pick_tasks_picked_sku FOREIGN KEY (picked_sku) REFERENCES products (sku)
);

CREATE TABLE qc_checks (
    qc_check_id              VARCHAR(10) NOT NULL,
