    CONSTRAINT pk_qc_checks PRIMARY KEY (qc_check_id),
    CONSTRAINT uq_qc_checks UNIQUE (order_id, attempt_no)
--  CONSTRAINT fk_qc_checks_order_id FOREIGN KEY (order_id) REFERENCES orders (order_id)   -- not enforceable on raw data
);

CREATE TABLE shipments (
    shipment_id              VARCHAR(10) NOT NULL,
