    CONSTRAINT pk_shipments PRIMARY KEY (shipment_id),
    CONSTRAINT uq_shipments UNIQUE (order_id)
--  CONSTRAINT fk_shipments_order_id FOREIGN KEY (order_id) REFERENCES orders (order_id)   -- not enforceable on raw data
