    CONSTRAINT pk_invoices PRIMARY KEY (invoice_id),
    CONSTRAINT uq_invoices UNIQUE (order_id),
--  CONSTRAINT fk_invoices_order_id FOREIGN KEY (order_id) REFERENCES orders (order_id)   -- not enforceable on raw data
